"""Marketing workflow workspace for reviewed lifecycle follow-up."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM workflow workspace"], include_in_schema=False)
_HEADERS = {
    "Cache-Control": "no-store",
    "Content-Security-Policy": "default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff",
}
_PAGE = """<!doctype html>
<html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>اتوماسیون و گردش‌کار | فانل CRM</title>
<style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px minmax(0,1fr)}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:800;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav:hover,.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top{display:flex;align-items:center;gap:10px;margin-bottom:24px}.field{display:grid;gap:6px;font-size:11px;color:#778697}select,input,textarea{font:inherit;color:#33465c;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:140px}.head{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:17px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap}button{font:inherit;cursor:pointer}.primary{border:0;background:#126b91;color:white;border-radius:9px;padding:11px 16px;font-weight:700}.secondary{border:1px solid #d8e2ea;background:white;color:#31536c;border-radius:8px;padding:9px 12px}.status{min-height:20px;color:#718092;font-size:12px;margin:0 0 8px}.status.error{color:#a74137}.stepbar{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.step{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #e5eaf0;border-radius:10px;padding:12px}.step b{width:25px;height:25px;border-radius:50%;display:grid;place-items:center;background:#e6f2f4;color:#17687c;font-size:11px;flex:0 0 auto}.step span{color:#52677a;font-size:11px;line-height:1.6}.kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:11px}.value{font-size:22px;font-weight:800;color:#1a334c;margin:8px 0 3px}.meta{font-size:10px;color:#8290a0;line-height:1.7}.grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(270px,.65fr);gap:14px}.title-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 12px}.title-row h2{font-size:15px;margin:0}.row{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:600px;font-size:11px}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid #eef1f4;vertical-align:middle}th{background:#f8fafc;color:#728092;font-weight:600}td{color:#33465c}.check{width:17px;height:17px;min-width:0;accent-color:#126b91}.person strong{display:block;font-size:12px}.person small{display:block;color:#8793a0;margin-top:5px;line-height:1.7}.pill{display:inline-block;padding:4px 8px;border-radius:99px;background:#eff4f7;color:#506879;font-size:10px}.empty{border:1px dashed #d4dde6;border-radius:9px;padding:18px;color:#7b8998;font-size:12px;text-align:center;line-height:1.8}.form{display:grid;gap:11px}.form textarea{min-height:70px;resize:vertical}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 0}.notice{border-right:3px solid #d59a3a;background:#fff9ed;color:#715820;border-radius:7px;padding:10px 12px;font-size:10px;line-height:1.8;margin-top:12px}.queue{display:grid;gap:8px}.task{border:1px solid #e8edf2;border-radius:9px;padding:10px}.task strong{font-size:12px}.task p{font-size:10px;color:#788696;margin:5px 0 0;line-height:1.7}.source-note{font-size:10px;color:#8793a0;line-height:1.8;margin-top:12px}
@media(max-width:1000px){.grid{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:9px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.head{display:block}.filters{margin-top:13px}.stepbar{grid-template-columns:1fr}}@media(max-width:480px){.main{padding:15px 12px 32px}.top{align-items:stretch;flex-direction:column}.top select{width:100%}.filters{display:grid;grid-template-columns:1fr 1fr}.filters select,.filters input{min-width:0;width:100%}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}.form-row{grid-template-columns:1fr}.primary{padding:10px 12px}}
</style><script src="/assets/crm-workflow-workspace.js" defer></script></head>
<body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-customers">مشتریان</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav" href="/workspace/crm-sales">فروش و درآمد</a><a class="nav" href="/workspace/crm-operations">عملیات و منابع</a><a class="nav" href="/workspace/crm-analytics">تحلیل و هوش تجاری</a><a class="nav" href="/workspace/crm-assistant">دستیار مدیر بازاریابی</a><a class="nav active" href="/workspace/crm-workflows" aria-current="page">اتوماسیون و گردش‌کار</a></nav></aside>
<main class="main"><div class="top"><label class="field">فضای کاری<select id="workspace-id"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="organization-unit"><option value="">ابتدا فضای کاری را انتخاب کنید</option></select></label></div>
<header class="head"><div><h1>اتوماسیون و گردش‌کار</h1><p class="sub">یک قانون پیگیری را تعیین کنید، موارد منطبق را بازبینی کنید و فقط موارد انتخاب‌شده را به صف کار تبدیل کنید.</p></div><div class="filters"><label class="field">عدم ثبت فعالیت برای<select id="inactive-days"><option value="30">۳۰ روز</option><option value="60">۶۰ روز</option><option value="90">۹۰ روز</option><option value="180">۱۸۰ روز</option></select></label><button id="review" class="primary" type="button">بازبینی موارد</button></div></header>
<p id="status" class="status" role="status" aria-live="polite"></p>
<div class="stepbar" aria-label="مراحل گردش‌کار"><div class="step"><b>۱</b><span>تعریف شرط: نبود فعالیت ثبت‌شده برای تعداد روز انتخابی</span></div><div class="step"><b>۲</b><span>بازبینی و انتخاب دستی مشتریان منطبق</span></div><div class="step"><b>۳</b><span>ساخت کار پیگیری و ثبت آن در صف CRM</span></div></div>
<section class="kpis"><article class="card"><div class="label">موارد منطبق با شرط</div><div id="candidate-count" class="value">—</div><div class="meta">در واحد سازمانی انتخاب‌شده</div></article><article class="card"><div class="label">انتخاب‌شده برای پیگیری</div><div id="selected-count" class="value">۰</div><div class="meta">حداکثر ۵۰ پرونده در هر اجرا</div></article><article class="card"><div class="label">کارهای باز صف</div><div id="open-count" class="value">—</div><div class="meta">کارهای باز واحد سازمانی</div></article></section>
<div class="grid"><section class="card"><div class="title-row"><h2>بازبینی مشتریان منطبق</h2><span id="candidate-meta" class="meta"></span></div><div id="candidates" class="table-wrap"><div class="empty">فضا و واحد سازمانی را انتخاب کنید، سپس موارد منطبق با شرط را بارگذاری کنید.</div></div><div class="actions"><button id="select-visible" class="secondary" type="button">انتخاب موارد نمایش‌داده‌شده</button><button id="clear-selection" class="secondary" type="button">پاک‌کردن انتخاب</button></div><p id="basis" class="source-note"></p></section>
<section class="card"><h2 class="title-row">ساخت کارهای پیگیری</h2><form id="workflow-form" class="form"><label class="field">عنوان کار<input id="title-prefix" maxlength="80" value="پیگیری چرخهٔ عمر" required></label><label class="field">شرح کار<textarea id="description" maxlength="1500" placeholder="متن مشترک برای اعضای صف"></textarea></label><div class="form-row"><label class="field">اولویت<select id="priority"><option value="normal">معمولی</option><option value="low">کم</option><option value="high">بالا</option><option value="urgent">فوری</option></select></label><label class="field">موعد<input id="due-at" type="datetime-local"></label></div><button id="create-tasks" class="primary" type="submit">ساخت کارها برای انتخاب‌شده‌ها</button></form><div class="notice">پیش از ساخت، موارد را بازبینی و انتخاب می‌کنید. API دوباره شرط عدم فعالیت را بررسی می‌کند و اگر داده تغییر کرده باشد، اجرای دسته‌ای را رد می‌کند.</div></section>
<section class="card"><div class="title-row"><h2>صف پیگیری‌های باز</h2><button id="refresh-queue" class="secondary" type="button">به‌روزرسانی</button></div><div id="open-queue" class="queue"><div class="empty">برای مشاهدهٔ صف، واحد سازمانی را انتخاب کنید.</div></div><p class="source-note">این صفحه گردش‌کار بازبینی و ایجاد کار را اجرا می‌کند. اجرای زمان‌بندی‌شده یا قواعدی که بدون تأیید مدیر خودکار عمل کنند، هنوز در APIهای مخزن پیاده‌سازی نشده‌اند.</p></section></div></main></div></body></html>"""
_SCRIPT = """(() => {
const $=id=>document.getElementById(id),workspace=$("workspace-id"),unit=$("organization-unit"),fmt=new Intl.NumberFormat("fa-IR");
let candidates=[],selected=new Set(),candidateRule=null;
function say(text,error=false){$("status").textContent=text;$("status").classList.toggle("error",error)}
function el(tag,text,cls=""){const n=document.createElement(tag);n.textContent=String(text??"");if(cls)n.className=cls;return n}
async function api(path,options={}){const headers={Accept:"application/json",...(options.headers||{})};if(options.body)headers["Content-Type"]="application/json";if(workspace.value)headers["X-Workspace-ID"]=workspace.value;const res=await fetch(path,{credentials:"same-origin",...options,headers});let data={};try{data=res.status===204?{}:await res.json()}catch(_){}if(!res.ok){const d=typeof data.detail==="string"?data.detail:data.detail?.message;throw Error(d||"درخواست ناموفق بود ("+res.status+").")}return data}
function updateSelectionCount(){$("selected-count").textContent=fmt.format(selected.size)}
function renderCandidates(data){candidates=data.candidates||[];candidateRule={inactive_for_days:data.inactive_for_days,organization_unit_id:unit.value};const host=$("candidates");host.replaceChildren();$("candidate-count").textContent=fmt.format(data.total||0);$("candidate-meta").textContent=fmt.format(candidates.length)+" از "+fmt.format(data.total||0)+" مورد";$("basis").textContent=(data.basis||"مبنای فهرست در API موجود نیست")+" "+(data.contact_action_executed?"اقدام ارتباطی انجام شده است.":"این گزارش صرفاً پرونده‌های منطبق را فهرست می‌کند و تماس یا پیام ارسال نمی‌کند.");if(!candidates.length){host.appendChild(el("div","مشتری منطبقی برای این شرط پیدا نشد.","empty"));return}const table=document.createElement("table"),thead=document.createElement("thead"),hr=document.createElement("tr");["انتخاب","پرونده","مرحله","آخرین فعالیت","علت"].forEach(x=>hr.appendChild(el("th",x)));thead.appendChild(hr);table.appendChild(thead);const body=document.createElement("tbody");candidates.forEach(c=>{const tr=document.createElement("tr"),td=document.createElement("td"),cb=document.createElement("input");cb.type="checkbox";cb.className="check";cb.checked=selected.has(c.profile_id);cb.setAttribute("aria-label","انتخاب "+c.display_name);cb.addEventListener("change",()=>{if(cb.checked){if(selected.size>=50){cb.checked=false;say("حداکثر ۵۰ پرونده را می‌توان در یک اجرا انتخاب کرد.",true);return}selected.add(c.profile_id)}else selected.delete(c.profile_id);updateSelectionCount()});td.appendChild(cb);tr.appendChild(td);const person=document.createElement("td");person.className="person";person.appendChild(el("strong",c.display_name));person.appendChild(el("small",(c.profile_kind||"")+" · "+(c.days_since_recorded_activity===null?"بدون فعالیت ثبت‌شده":fmt.format(c.days_since_recorded_activity)+" روز از آخرین فعالیت")));tr.appendChild(person);tr.appendChild(el("td",c.current_lifecycle_stage||"—"));tr.appendChild(el("td",c.latest_recorded_activity_at?new Date(c.latest_recorded_activity_at).toLocaleDateString("fa-IR"):"ثبت نشده"));tr.appendChild(el("td",c.reason||"—"));body.appendChild(tr)});table.appendChild(body);host.appendChild(table);updateSelectionCount()}
async function loadCandidates(){if(!workspace.value||!unit.value){say("فضای کاری و واحد سازمانی را انتخاب کنید.",true);return}say("در حال بررسی پرونده‌های منطبق…");try{const params=new URLSearchParams({inactive_for_days:$("inactive-days").value,organization_unit_id:unit.value,limit:"50"});const data=await api("/api/v1/crm/analytics/customer-lifecycle/follow-up-candidates?"+params.toString());selected.clear();renderCandidates(data);say("فهرست بازبینی آماده شد.")}catch(e){say(e.message,true)}}
function localDue(){const value=$("due-at").value;return value?new Date(value).toISOString():null}
async function createTasks(ev){ev.preventDefault();if(!candidateRule||!selected.size){say("ابتدا موارد را بارگذاری و دست‌کم یک پرونده را انتخاب کنید.",true);return}const body={organization_unit_id:candidateRule.organization_unit_id,profile_ids:[...selected],inactive_for_days:candidateRule.inactive_for_days,title_prefix:$("title-prefix").value,description:$("description").value||null,priority:$("priority").value,due_at:localDue()};const button=$("create-tasks");button.disabled=true;say("در حال ساخت کارهای پیگیری…");try{const result=await api("/api/v1/crm/work-items/from-lifecycle-review",{method:"POST",body:JSON.stringify(body)});const count=result.created_count||result.items?.length||0;selected.clear();updateSelectionCount();say(fmt.format(count)+" کار پیگیری در صف CRM ساخته شد.");await Promise.all([loadQueue(),loadCandidates()])}catch(e){say(e.message+" در صورت تغییر داده، فهرست را دوباره بازبینی کنید.",true)}finally{button.disabled=false}}
async function loadQueue(){if(!unit.value){$("open-queue").replaceChildren(el("div","برای مشاهدهٔ صف، واحد سازمانی را انتخاب کنید.","empty"));return}try{const params=new URLSearchParams({organization_unit_id:unit.value,status:"open",limit:"100"});const rows=await api("/api/v1/crm/work-items?"+params.toString());$("open-count").textContent=fmt.format(rows.length);const host=$("open-queue");host.replaceChildren();if(!rows.length){host.appendChild(el("div","کار بازی در واحد نیست.","empty"));return}rows.slice(0,12).forEach(t=>{const row=document.createElement("article");row.className="task";row.appendChild(el("strong",t.title));row.appendChild(el("p",(t.due_at?"موعد "+new Date(t.due_at).toLocaleString("fa-IR")+" · ":"")+(t.priority==="urgent"?"فوری":t.priority==="high"?"بالا":"معمولی")));host.appendChild(row)})}catch(e){$("open-queue").replaceChildren(el("div",e.message,"empty"));$("open-count").textContent="—"}}
async function loadUnits(){unit.replaceChildren();const p=el("option","واحد سازمانی را انتخاب کنید");p.value="";unit.appendChild(p);if(!workspace.value)return;const rows=await api("/api/v1/system/organization-units");rows.forEach(x=>{const o=el("option",x.name);o.value=x.id;unit.appendChild(o)});if(rows.length===1)unit.value=rows[0].id;if(unit.value){await loadQueue();await loadCandidates()}else say("واحد سازمانی را انتخاب کنید.")}
async function init(){try{const spaces=await api("/api/v1/system/workspaces");workspace.replaceChildren();const p=el("option","فضای کاری را انتخاب کنید");p.value="";workspace.appendChild(p);spaces.forEach(s=>{const o=el("option",s.name);o.value=s.id;workspace.appendChild(o)});const wanted=new URLSearchParams(location.search).get("workspace_id");workspace.value=spaces.some(s=>s.id===wanted)?wanted:(spaces.length===1?spaces[0].id:"");if(workspace.value)await loadUnits();else say("فضای کاری را انتخاب کنید.")}catch(e){say(e.message,true)}}
workspace.addEventListener("change",async()=>{unit.value="";selected.clear();try{await loadUnits()}catch(e){say(e.message,true)}});unit.addEventListener("change",async()=>{selected.clear();candidateRule=null;updateSelectionCount();await Promise.all([loadCandidates(),loadQueue()])});$("review").addEventListener("click",loadCandidates);$("inactive-days").addEventListener("change",()=>{selected.clear();candidateRule=null;updateSelectionCount()});$("select-visible").addEventListener("click",()=>{candidates.slice(0,50).forEach(c=>selected.add(c.profile_id));updateSelectionCount();renderCandidates({candidates,total:candidates.length,inactive_for_days:candidateRule?.inactive_for_days||Number($("inactive-days").value),basis:"موارد بارگذاری‌شده",contact_action_executed:false})});$("clear-selection").addEventListener("click",()=>{selected.clear();updateSelectionCount();if(candidateRule)renderCandidates({candidates,total:candidates.length,inactive_for_days:candidateRule.inactive_for_days,basis:"موارد انتخاب‌شده پاک شد.",contact_action_executed:false})});$("workflow-form").addEventListener("submit",createTasks);$("refresh-queue").addEventListener("click",loadQueue);init();
})();"""

@router.get("/workspace/crm-workflows", response_class=HTMLResponse)
async def crm_workflow_workspace_page() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-workflow-workspace.js")
async def crm_workflow_workspace_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff"})
